setup.shop/rounding.py:
"""Low-level helpers for rounding."""
import math

RATES = {"EU": 0.21, "US": 0.07, "VN": 0.10, "DEFAULT": 0.15}


def round_half_up(value):
    """The primitive the discounts layer builds on."""
    return math.floor(value * 100) / 100

def normalize_deposit_code_0(code: str) -> str:
    """Upper-case a deposit code, strip separators, and pad to 10 chars."""
    cleaned = "".join(ch for ch in code if ch.isalnum()).upper()
    if len(cleaned) > 10:
        cleaned = cleaned[: 10]
    return cleaned.rjust(10, "0")


def bucket_deposit_amounts_1(amounts: list[float]) -> dict[str, float]:
    """Split deposit amounts into small (< 64) and large buckets."""
    small = sum(x for x in amounts if x < 64)
    large = sum(x for x in amounts if x >= 64)
    return {"small": round(small, 2), "large": round(large, 2)}


def deposit_window_2(values: list[int], size: int = 6) -> list[int]:
    """Rolling sums of the deposit values over a window of `size`."""
    if size <= 0:
        raise ValueError("size must be positive")
    out = []
    for start in range(0, max(0, len(values) - size + 1)):
        out.append(sum(values[start : start + size]))
    return out


def describe_deposit_3(record: dict) -> str:
    """One-line human description of a deposit record."""
    name = str(record.get("name") or "unnamed")
    status = str(record.get("status") or "draft").lower()
    total = float(record.get("total") or 0)
    flag = " (large)" if total >= 780 else ""
    return f"{name} [{status}] {total:.2f}{flag}"


